// Loads the synthetic dataset from ./data (generated by scripts/generate-data.js and committed).
import { readFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
export const DATA_DIR = join(ROOT, "data");

const read = (name) => JSON.parse(readFileSync(join(DATA_DIR, name), "utf8"));

export function loadDataset() {
  if (!existsSync(join(DATA_DIR, "meta.json"))) {
    throw new Error("data/ is missing. Run `npm run data` to regenerate the synthetic dataset.");
  }
  const meta = read("meta.json");
  const retailers = read("retailers.json");
  const products = read("products.json");
  const history = read("history.json");
  const lists = read("lists.json");
  const kp = read("kp-listings.json");
  const pages = [1, 2, 3].map((n) => read(`feed/page-${n}.json`));
  const offersById = new Map(pages.flat().map((o) => [o.id, o]));
  return {
    meta, retailers, products, history, lists, kp, pages, offersById,
    retailerById: new Map(retailers.map((r) => [r.id, r])),
    productById: new Map(products.map((p) => [p.id, p])),
    kpById: new Map(kp.map((l) => [l.id, l])),
  };
}

export const feedPagePath = (n) => join(DATA_DIR, "feed", `page-${n}.json`);
